/// <summary>
/// Allow tobacco items with T values.
/// </summary>
/// <param name = "_conditionValue">GUPAttributeValue</param>
/// <returns>Boolean</returns>
public static boolean existsUnsupportedOperators(GUPAttributeValue _conditionValue)
{
    boolean ret = next existsUnsupportedOperators(_conditionValue);

    if (_conditionValue == METConstants::T && ret == true)
    {
        return false;
    }

    return ret;
}
